import React, { useState } from "react";
import api from "../api";

function MealPlan({ familyId }) {
    const [plan, setPlan] = useState(null);
    const [loading, setLoading] = useState(false);

    const generatePlan = async () => {
        try {
            setLoading(true);

            const res = await api.get(
                `/families/${familyId}/mealplan`
            );

            setPlan(res.data);
        } catch (error) {
            console.error(
                "Error generating meal plan:",
                error
            );
        } finally {
            setLoading(false);
        }
    };

    return (
        <div>
            <button onClick={generatePlan}>
                {loading
                    ? "Generating..."
                    : "Generate AI Meal Plan"}
            </button>

            {plan && (
                <div className="card">
                    <h4>Meal Plan</h4>

                    {plan.meal_plan ? (
                        <pre>{plan.meal_plan}</pre>
                    ) : (
                        <>
                            <p>
                                Breakfast:{" "}
                                {plan.breakfast}
                            </p>
                            <p>
                                Lunch: {plan.lunch}
                            </p>
                            <p>
                                Dinner: {plan.dinner}
                            </p>
                        </>
                    )}

                    {plan.members && (
                        <p>
                            <strong>Members:</strong>{" "}
                            {plan.members.join(", ")}
                        </p>
                    )}

                    {plan.note && (
                        <p>
                            <strong>Note:</strong>{" "}
                            {plan.note}
                        </p>
                    )}
                </div>
            )}
        </div>
    );
}

export default MealPlan;
